-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 42 recettes, 18 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"patatnik-rhodopes","country":"BG","place":{"slug":"bg-rhodopes","name":"Rhodopes","type":"region","lat":41.6,"lng":24.7,"summary":"Massif montagneux du sud de la Bulgarie, berceau du patatnik et de la cuisine des bergers."},"original":"Patatnik","title":"Patatnik des Rhodopes (galette de pommes de terre au fromage)","en":"Rhodope patatnik (potato and cheese bake)","es":"Patatnik de los Ródopes","desc":"Pommes de terre râpées, oignon, fromage sirene et menthe sèche cuits lentement en galette épaisse et dorée, spécialité des montagnes des Rhodopes.","cat":"Plat principal","diff":"easy","prep":25,"cook":60,"serv":6,"reference":"https://en.wikipedia.org/wiki/Patatnik","ing":[["Pommes de terre",1.5,"kg","râpées et pressées"],["Oignons",2,null,"hachés"],["Fromage sirene (ou feta)",200,"g","émietté"],["Œufs",2,null,null],["Menthe séchée",1,"c. à soupe",null],["Beurre",60,"g",null],["Huile",3,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Presser les pommes de terre râpées pour retirer l’eau; les mélanger avec oignons, sel et poivre et laisser 15 minutes.","Ajouter œufs, fromage et menthe séchée.","Chauffer beurre et huile dans une poêle épaisse ou un plat en terre, y tasser le mélange.","Cuire à couvert 30 minutes à feu doux, retourner sur une assiette et cuire l’autre face 20 minutes (ou finir au four à 200 °C).","Servir chaud en parts, avec du yaourt."],"photo":{"file":"File:Patatnik.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/24/Patatnik.jpg","page":"https://commons.wikimedia.org/wiki/File:Patatnik.jpg","author":"K kapustin","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"mekitsi-bg","country":"BG","original":"Mekitsi","title":"Mekitsi bulgares (beignets au yaourt, sucre glace et confiture)","en":"Bulgarian mekitsi (yogurt fritters)","es":"Mekitsi búlgaros (buñuelos de yogur)","desc":"Beignets de pâte levée au yaourt, étirés à la main et frits, servis au petit-déjeuner avec sucre glace, confiture, miel ou fromage.","cat":"Petit-déjeuner","diff":"easy","prep":20,"cook":20,"serv":6,"reference":"https://en.wikipedia.org/wiki/Mekitsa","ing":[["Farine",450,"g",null],["Yaourt bulgare",250,"g",null],["Œuf",1,null,null],["Levure chimique",1,"c. à thé",null],["Bicarbonate",0.5,"c. à thé",null],["Sel",1,"c. à thé",null],["Huile",750,"ml","pour la friture"],["Sucre glace et confiture",1,"portion","pour servir"]],"steps":["Mélanger yaourt, bicarbonate et œuf; ajouter farine, levure et sel pour une pâte molle.","Laisser reposer 20 minutes sous un linge.","Avec les mains huilées, prendre des morceaux de pâte et les étirer en galettes irrégulières.","Frire à 175 °C 1 à 2 minutes par face jusqu’à ce qu’ils soient dorés.","Saupoudrer de sucre glace et servir avec confiture."],"photo":{"file":"File:Mekici.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Mekici.jpg/1280px-Mekici.jpg","page":"https://commons.wikimedia.org/wiki/File:Mekici.jpg","author":"C00lfon","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"varza-a-la-cluj","country":"RO","place":{"slug":"ro-cluj","name":"Cluj-Napoca","type":"city","lat":46.7712,"lng":23.6236,"summary":"Capitale historique de la Transylvanie, qui donne son nom au chou à la mode de Cluj."},"original":"Varză a la Cluj","title":"Varză à la Cluj (gratin de chou, porc et riz à la crème)","en":"Cluj-style cabbage bake","es":"Varză a la Cluj (gratinado de col y cerdo)","desc":"Couches de chou aigre ou frais, de porc haché au riz et de lard, cuites au four sous la crème aigre; plat transylvanien de Cluj.","cat":"Plat principal","diff":"medium","prep":40,"cook":90,"serv":6,"reference":"https://en.wikipedia.org/wiki/Varz%C4%83_a_la_Cluj","ing":[["Chou aigre (ou chou frais)",1.5,"kg","émincé"],["Porc haché",600,"g",null],["Riz",100,"g",null],["Oignons",2,null,"hachés"],["Lard fumé",150,"g","en tranches"],["Crème aigre",400,"g",null],["Concentré de tomate",2,"c. à soupe",null],["Paprika et thym",2,"c. à thé",null],["Huile",3,"c. à soupe",null],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Faire revenir le chou avec un peu d’huile et le concentré 20 minutes.","Faire revenir oignons et viande, ajouter le riz, le paprika, le thym, sel et poivre, et 150 ml d’eau; cuire 10 minutes.","Dans un plat, alterner chou, viande et chou, en finissant par le chou.","Couvrir de lard et de crème aigre délayée avec un peu d’eau.","Cuire 1 heure à 180 °C et servir avec de la crème."],"photo":{"file":"File:Varza a la Cluj.png","url":"https://upload.wikimedia.org/wikipedia/commons/7/7f/Varza_a_la_Cluj.png","page":"https://commons.wikimedia.org/wiki/File:Varza_a_la_Cluj.png","author":"Sacha47","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"ciorba-radauteana","country":"RO","place":{"slug":"ro-radauti","name":"Rădăuți","type":"city","lat":47.8429,"lng":25.9196,"summary":"Ville de Bucovine qui a donné son nom à la ciorbă rădăuțeană."},"original":"Ciorbă rădăuțeană","title":"Ciorbă rădăuțeană (soupe aigre de poulet à la crème et à l’ail, Bucovine)","en":"Rădăuți chicken sour soup","es":"Ciorbă rădăuțeană (sopa agria de pollo)","desc":"Soupe de poulet aigrelette liée au jaune d’œuf et à la crème aigre, relevée d’ail et de vinaigre, née à Rădăuți en Bucovine.","cat":"Soupe","diff":"medium","prep":20,"cook":75,"serv":6,"reference":"https://ro.wikipedia.org/wiki/Ciorb%C4%83_r%C4%83d%C4%83u%C8%9Bean%C4%83","ing":[["Poulet",1,"kg","en morceaux"],["Carottes",2,null,"en dés"],["Céleri-rave",100,"g","en dés"],["Poivron",1,null,"en dés"],["Oignon",1,null,null],["Crème aigre",250,"g",null],["Jaunes d’œufs",3,null,null],["Ail",5,"gousses","pilées"],["Vinaigre",3,"c. à soupe",null],["Sel",2,"c. à thé",null]],"steps":["Cuire le poulet 45 minutes dans 2,5 litres d’eau salée avec l’oignon, en écumant.","Retirer le poulet, l’effilocher; ajouter les légumes au bouillon et cuire 20 minutes.","Fouetter crème aigre et jaunes, puis tempérer avec une louche de bouillon chaud.","Hors du feu, verser la liaison dans la soupe, ajouter ail, vinaigre et poulet.","Chauffer sans bouillir et servir avec piment fort."],"photo":{"file":"File:Ciorba radauteana.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/df/Ciorba_radauteana.jpg","page":"https://commons.wikimedia.org/wiki/File:Ciorba_radauteana.jpg","author":"Romaniancook","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"bulz-ciobanesc","country":"RO","original":"Bulz","title":"Bulz ciobănesc (boules de polenta au fromage grillées)","en":"Romanian shepherd’s bulz","es":"Bulz ciobănesc (bolas de polenta con queso)","desc":"Boules de mămăligă farcies de fromage de brebis (telemea, brânză de burduf), grillées ou cuites au four, plat des bergers des Carpates.","cat":"Plat principal","diff":"easy","prep":20,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Bulz","ing":[["Semoule de maïs",300,"g",null],["Eau",1.2,"l",null],["Fromage de brebis (telemea ou burduf)",250,"g",null],["Beurre",40,"g",null],["Œufs",4,null,"facultatif"],["Crème aigre",200,"g","pour servir"],["Sel",1,"c. à thé",null]],"steps":["Cuire une mămăligă ferme : semoule en pluie dans l’eau bouillante salée, 20 minutes en remuant.","Avec les mains mouillées, former des boules en y enfermant un morceau de fromage.","Les poser sur une plaque beurrée (ou dans des papillotes d’aluminium).","Cuire 15 à 20 minutes à 200 °C ou sur la grille jusqu’à ce qu’elles dorent.","Servir avec crème aigre et, si désiré, un œuf au plat."],"photo":{"file":"File:Bulz ciobănesc.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Bulz_ciob%C4%83nesc.jpg/1280px-Bulz_ciob%C4%83nesc.jpg","page":"https://commons.wikimedia.org/wiki/File:Bulz_ciob%C4%83nesc.jpg","author":"Nicubunu","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"beryani-isfahan","country":"IR","place":{"slug":"ir-isfahan","name":"Ispahan","type":"city","lat":32.6546,"lng":51.668,"summary":"Ancienne capitale safavide, réputée pour son beryani et son gaz."},"original":"Beryani","title":"Beryani d’Ispahan (agneau haché et poumon grillés sur pain sangak)","en":"Isfahani beryani","es":"Beryani de Isfahán","desc":"Viande d’agneau hachée et poêlée en galette avec épices et cannelle, servie sur pain sangak avec amandes, pistaches et herbes fraîches; spécialité d’Ispahan.","cat":"Plat principal","diff":"medium","prep":30,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Beryani","ing":[["Épaule d’agneau",600,"g",null],["Oignon",1,null,null],["Curcuma",1,"c. à thé",null],["Cannelle",1,"c. à thé",null],["Safran infusé",2,"c. à soupe",null],["Amandes et pistaches effilées",30,"g",null],["Pain sangak ou lavash",4,null,null],["Herbes fraîches, radis et oignon",1,"portion",null],["Huile",3,"c. à soupe",null],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Cuire l’agneau 1 heure avec l’oignon, le curcuma et un peu d’eau, puis l’égoutter.","Le hacher très finement avec cannelle, sel et poivre.","Dans une petite poêle huilée, tasser une portion de viande en galette et la cuire 5 minutes avec un peu de safran.","Parsemer d’amandes et de pistaches.","Retourner la galette sur un pain sangak et servir avec herbes, radis et bouillon."],"photo":{"file":"File:Iranianbyryani2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Iranianbyryani2.jpg/1280px-Iranianbyryani2.jpg","page":"https://commons.wikimedia.org/wiki/File:Iranianbyryani2.jpg","author":"پوویا","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"sohan-qom","country":"IR","place":{"slug":"ir-qom","name":"Qom","type":"city","lat":34.6399,"lng":50.8759,"summary":"Ville sainte du centre de l’Iran, célèbre pour son sohan au safran."},"original":"Sohan","title":"Sohan de Qom (croquant au safran et aux pistaches)","en":"Qom sohan (saffron brittle)","es":"Sohan de Qom (crocante de azafrán)","desc":"Croquant iranien au beurre, sucre, farine de blé germé, safran et cardamome, parsemé de pistaches et d’amandes; confiserie emblématique de Qom.","cat":"Dessert","diff":"medium","prep":15,"cook":30,"serv":12,"reference":"https://en.wikipedia.org/wiki/Sohan_(confectionery)","ing":[["Sucre",200,"g",null],["Beurre clarifié",120,"g",null],["Farine",60,"g",null],["Miel",3,"c. à soupe",null],["Safran infusé",3,"c. à soupe",null],["Cardamome",1,"c. à thé",null],["Pistaches et amandes effilées",80,"g",null],["Eau de rose",1,"c. à soupe",null]],"steps":["Faire dorer la farine dans le beurre clarifié 5 minutes.","Ajouter sucre et miel et cuire en remuant jusqu’à couleur ambrée (environ 15 minutes).","Ajouter safran, cardamome et eau de rose hors du feu.","Verser en petits disques sur une plaque huilée et parsemer de pistaches et d’amandes.","Laisser durcir puis conserver dans une boîte hermétique."],"photo":{"file":"File:Sohan Qom.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/64/Sohan_Qom.jpg","page":"https://commons.wikimedia.org/wiki/File:Sohan_Qom.jpg","author":"User:SohanSeri","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"faloodeh-shirazi","country":"IR","place":{"slug":"ir-shiraz","name":"Chiraz","type":"city","lat":29.5918,"lng":52.5837,"summary":"Ville des poètes et des jardins, patrie du faloodeh et de la salade shirazi."},"original":"Faloodeh","title":"Faloodeh de Chiraz (vermicelles glacés à l’eau de rose et au citron)","en":"Shirazi faloodeh","es":"Faloodeh de Shiraz","desc":"Fins vermicelles d’amidon pris dans un sorbet à moitié glacé d’eau de rose et de sucre, servis avec jus de citron vert; dessert d’été de Chiraz.","cat":"Dessert","diff":"medium","prep":20,"cook":10,"serv":6,"reference":"https://en.wikipedia.org/wiki/Faloodeh","ing":[["Vermicelles de riz très fins",80,"g",null],["Sucre",200,"g",null],["Eau",600,"ml",null],["Eau de rose",3,"c. à soupe",null],["Citrons verts",3,null,"jus"],["Griottes au sirop",2,"c. à soupe","facultatif"]],"steps":["Chauffer eau et sucre jusqu’à dissolution, ajouter l’eau de rose et refroidir.","Cuire les vermicelles 2 minutes, les rincer à l’eau glacée et les couper en tronçons de 5 cm.","Mélanger vermicelles et sirop dans un plat et placer au congélateur.","Gratter à la fourchette toutes les 30 minutes pendant 3 heures pour obtenir des cristaux.","Servir en coupes avec jus de citron vert et griottes."],"photo":{"file":"File:Faloodeh1.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Faloodeh1.jpg/1280px-Faloodeh1.jpg","page":"https://commons.wikimedia.org/wiki/File:Faloodeh1.jpg","author":"Rka11111","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"salad-shirazi","country":"IR","place":{"slug":"ir-shiraz","name":"Chiraz","type":"city","lat":29.5918,"lng":52.5837,"summary":"Ville des poètes et des jardins, patrie du faloodeh et de la salade shirazi."},"original":"Salad Shirazi","title":"Salade shirazi (concombre, tomate et oignon au verjus)","en":"Shirazi salad","es":"Ensalada shirazi","desc":"Petits dés de concombre, tomate et oignon rouge assaisonnés de verjus ou de citron vert, de menthe séchée et d’huile d’olive; accompagnement de Chiraz.","cat":"Entrée","diff":"easy","prep":15,"cook":0,"serv":4,"reference":"https://en.wikipedia.org/wiki/Shirazi_salad","ing":[["Concombres",3,null,"en petits dés"],["Tomates",3,null,"en petits dés"],["Oignon rouge",1,null,"finement haché"],["Verjus ou jus de citron vert",4,"c. à soupe",null],["Menthe séchée",1,"c. à thé",null],["Huile d’olive",2,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Couper concombres, tomates et oignon en dés de 5 mm.","Les réunir dans un saladier.","Assaisonner de verjus, huile, sel et poivre.","Parsemer de menthe séchée frottée entre les doigts.","Réfrigérer 20 minutes et servir avec riz et kebab."],"photo":{"file":"File:Salad Shirazi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/aa/Salad_Shirazi.jpg","page":"https://commons.wikimedia.org/wiki/File:Salad_Shirazi.jpg","author":"MRG90","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"gaz-isfahan","country":"IR","place":{"slug":"ir-isfahan","name":"Ispahan","type":"city","lat":32.6546,"lng":51.668,"summary":"Ancienne capitale safavide, réputée pour son beryani et son gaz."},"original":"Gaz","title":"Gaz d’Ispahan (nougat persan aux pistaches et à l’eau de rose)","en":"Isfahani gaz (Persian nougat)","es":"Gaz de Isfahán (turrón persa)","desc":"Nougat tendre aux blancs d’œufs, sucre, eau de rose et pistaches, autrefois fait avec la manne de tamaris; confiserie d’Ispahan roulée dans la farine.","cat":"Dessert","diff":"hard","prep":30,"cook":30,"serv":20,"reference":"https://en.wikipedia.org/wiki/Gaz_(candy)","ing":[["Sucre",400,"g",null],["Glucose ou miel",150,"g",null],["Eau",120,"ml",null],["Blancs d’œufs",2,null,null],["Eau de rose",2,"c. à soupe",null],["Pistaches",200,"g","entières"],["Farine",80,"g","grillée, pour enrober"]],"steps":["Cuire sucre, glucose et eau jusqu’à 140 °C.","Monter les blancs en neige ferme et y verser le sirop en filet en fouettant.","Continuer à fouetter 10 minutes en ajoutant l’eau de rose, jusqu’à ce que la pâte épaississe.","Incorporer les pistaches, étaler sur un plan fariné et laisser tiédir.","Couper en bouchées et les rouler dans la farine grillée."],"photo":{"file":"File:Iranian gaz candy, close view 1.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Iranian_gaz_candy%2C_close_view_1.jpg/1280px-Iranian_gaz_candy%2C_close_view_1.jpg","page":"https://commons.wikimedia.org/wiki/File:Iranian_gaz_candy,_close_view_1.jpg","author":"Sebleouf","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"tulsky-pryanik","country":"RU","place":{"slug":"ru-tula","name":"Toula","type":"city","lat":54.1931,"lng":37.6173,"summary":"Ville au sud de Moscou, célèbre depuis le XVIIe siècle pour son pain d’épices imprimé."},"original":"Tulsky pryanik","title":"Pain d’épices de Toula (pryanik fourré à la confiture)","en":"Tula pryanik (filled gingerbread)","es":"Pryanik de Tula (pan de especias relleno)","desc":"Grand pain d’épices au miel imprimé d’un motif en relief et fourré de confiture ou de lait concentré, glacé au sucre; spécialité de Toula depuis le XVIIe siècle.","cat":"Dessert","diff":"medium","prep":40,"cook":25,"serv":8,"reference":"https://en.wikipedia.org/wiki/Tula_pryanik","ing":[["Farine",500,"g",null],["Miel",150,"g",null],["Sucre",100,"g",null],["Beurre",80,"g",null],["Œufs",2,null,null],["Bicarbonate",1,"c. à thé",null],["Cannelle, gingembre, girofle",2,"c. à thé",null],["Confiture épaisse (prune, pomme)",250,"g",null],["Sucre glace (glaçage)",150,"g",null]],"steps":["Chauffer miel, sucre et beurre jusqu’à dissolution; refroidir, ajouter œufs, épices et bicarbonate.","Incorporer la farine et pétrir une pâte souple; reposer 1 heure.","Étaler deux rectangles, étaler la confiture sur l’un et couvrir de l’autre; souder les bords et imprimer un motif.","Cuire 20 à 25 minutes à 180 °C.","Badigeonner encore chaud d’un glaçage de sucre glace et d’eau; laisser sécher."],"photo":{"file":"File:Tula gingerbread, Russian pryaniki (6362177535).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Tula_gingerbread%2C_Russian_pryaniki_%286362177535%29.jpg/1280px-Tula_gingerbread%2C_Russian_pryaniki_%286362177535%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Tula_gingerbread,_Russian_pryaniki_(6362177535).jpg","author":"Turku Gingerbread from Finland","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"pozharsky-torzhok","country":"RU","place":{"slug":"ru-torzhok","name":"Torjok","type":"city","lat":57.0414,"lng":34.9603,"summary":"Ville de l’oblast de Tver où l’auberge Pojarski créa ses célèbres croquettes."},"original":"Pozharskiye kotlety","title":"Côtelettes Pojarski de Torjok (croquettes de poulet panées au pain)","en":"Torzhok Pozharsky cutlets","es":"Chuletas Pozharsky de Torzhok","desc":"Croquettes de poulet haché au beurre et à la crème, panées de dés de pain de mie et dorées au beurre, nées à l’auberge Pojarski de Torjok.","cat":"Plat principal","diff":"medium","prep":30,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Pozharsky_cutlet","ing":[["Blancs et cuisses de poulet",700,"g","sans peau"],["Pain de mie rassis",200,"g","sans croûte"],["Lait ou crème",150,"ml",null],["Beurre froid",80,"g","en petits dés"],["Pain de mie en petits dés (panure)",150,"g",null],["Beurre (cuisson)",50,"g",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Tremper le pain dans le lait, l’essorer et le hacher avec le poulet.","Saler, poivrer et incorporer les dés de beurre froid.","Former des croquettes ovales avec les mains mouillées.","Les rouler dans les petits dés de pain.","Les dorer au beurre 4 à 5 minutes par face, puis finir 8 minutes au four à 180 °C; servir avec purée ou frites."],"photo":{"file":"File:Torzhok Pozharsky cutlets 016 0494.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Torzhok_Pozharsky_cutlets_016_0494.jpg/1280px-Torzhok_Pozharsky_cutlets_016_0494.jpg","page":"https://commons.wikimedia.org/wiki/File:Torzhok_Pozharsky_cutlets_016_0494.jpg","author":"Ludvig14","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"ukha-ru","country":"RU","original":"Ukha","title":"Oukha (soupe russe de poisson clair)","en":"Russian ukha (clear fish soup)","es":"Ujá rusa (sopa clara de pescado)","desc":"Bouillon limpide de poissons d’eau douce (sandre, perche, brochet) aux pommes de terre, oignon, laurier et aneth; traditionnellement préparé au bord des rivières.","cat":"Soupe","diff":"easy","prep":20,"cook":45,"serv":6,"reference":"https://en.wikipedia.org/wiki/Ukha","ing":[["Têtes et arêtes de poisson",500,"g",null],["Filets de sandre ou perche",600,"g","en morceaux"],["Pommes de terre",4,null,"en dés"],["Carotte",1,null,null],["Oignon",1,null,"entier"],["Laurier",2,"feuilles",null],["Poivre en grains",8,null,null],["Aneth",1,"bouquet",null],["Vodka",30,"ml","facultatif"],["Sel",1.5,"c. à thé",null]],"steps":["Cuire têtes et arêtes 25 minutes dans 2,5 litres d’eau avec l’oignon, le laurier et le poivre, puis filtrer.","Ajouter pommes de terre et carotte au bouillon; cuire 15 minutes.","Ajouter les morceaux de poisson et cuire 7 minutes à petit frémissement.","Saler et ajouter la vodka hors du feu.","Servir parsemé d’aneth, avec du pain noir."],"photo":{"file":"File:Тарелка с ухой.PNG","url":"https://upload.wikimedia.org/wikipedia/commons/9/94/%D0%A2%D0%B0%D1%80%D0%B5%D0%BB%D0%BA%D0%B0_%D1%81_%D1%83%D1%85%D0%BE%D0%B9.PNG","page":"https://commons.wikimedia.org/wiki/File:%D0%A2%D0%B0%D1%80%D0%B5%D0%BB%D0%BA%D0%B0_%D1%81_%D1%83%D1%85%D0%BE%D0%B9.PNG","author":"Аноним Инкогнитович at Russian Wikipedia","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"kebda-eskandarani","country":"EG","place":"eg-alexandria","original":"Kebda eskandarani","title":"Kebda eskandarani (foie sauté à l’alexandrine en sandwich)","en":"Alexandrian liver sandwich","es":"Kebda eskandarani (hígado a la alejandrina)","desc":"Fines lanières de foie de bœuf sautées très vite avec ail, piment vert, cumin et vinaigre, glissées dans du pain baladi; casse-croûte des rues d’Alexandrie.","cat":"Cuisine de rue","diff":"easy","prep":15,"cook":10,"serv":4,"ing":[["Foie de bœuf",500,"g","en fines lanières"],["Ail",5,"gousses","pilées"],["Piments verts",3,null,"émincés"],["Cumin",1.5,"c. à thé",null],["Vinaigre ou jus de citron",2,"c. à soupe",null],["Huile",4,"c. à soupe",null],["Pains baladi ou pitas",4,null,null],["Tahini et pickles",1,"portion","pour servir"],["Sel et poivre",1,"c. à thé",null]],"steps":["Assaisonner le foie de cumin, sel et poivre.","Saisir le foie à feu très vif dans l’huile 2 à 3 minutes.","Ajouter ail et piments, sauter 1 minute, puis déglacer au vinaigre.","Ouvrir les pains et les garnir de foie.","Servir avec tahini et pickles."],"photo":{"file":"File:Kebda eskandarani.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Kebda_eskandarani.jpg/1280px-Kebda_eskandarani.jpg","page":"https://commons.wikimedia.org/wiki/File:Kebda_eskandarani.jpg","author":"Turnopoems","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"molokhia-eg","country":"EG","original":"Molokhia","title":"Molokhia égyptienne (soupe de corète à l’ail et coriandre)","en":"Egyptian molokhia","es":"Molokhia egipcia","desc":"Feuilles de corète finement hachées cuites dans un bouillon de poulet ou de lapin, relevées d’une ta’leya d’ail et de coriandre grillés; servie avec riz et pain.","cat":"Soupe","diff":"medium","prep":20,"cook":60,"serv":6,"reference":"https://en.wikipedia.org/wiki/Mulukhiyah","ing":[["Feuilles de corète (molokhia) hachées",500,"g","fraîches ou surgelées"],["Bouillon de poulet",1.2,"l",null],["Poulet",1,"kg","cuit dans le bouillon"],["Ail",8,"gousses","pilées"],["Coriandre moulue",2,"c. à thé",null],["Beurre clarifié",30,"g",null],["Sel",1,"c. à thé",null],["Citron",1,null,"pour servir"]],"steps":["Porter le bouillon à frémissement et y verser la molokhia en remuant.","Cuire 5 minutes sans laisser bouillir fort, pour qu’elle ne retombe pas au fond.","Faire dorer l’ail dans le beurre avec la coriandre (ta’leya).","Verser la ta’leya grésillante dans la soupe et saler.","Servir avec le poulet, du riz et un filet de citron."],"photo":{"file":"File:Molokhia.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Molokhia.JPG/1280px-Molokhia.JPG","page":"https://commons.wikimedia.org/wiki/File:Molokhia.JPG","author":"Showshow777","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"om-ali","country":"EG","place":"eg-cairo","original":"Om Ali","title":"Om Ali (pudding égyptien de pâte feuilletée au lait et aux noix)","en":"Egyptian Om Ali","es":"Om Ali egipcio","desc":"Pâte feuilletée émiettée, noix, raisins secs et noix de coco nappés de lait sucré et de crème, gratinés au four; dessert servi chaud dans les cafés du Caire.","cat":"Dessert","diff":"easy","prep":15,"cook":25,"serv":6,"reference":"https://en.wikipedia.org/wiki/Umm_Ali","ing":[["Pâte feuilletée cuite",300,"g","émiettée"],["Lait entier",1,"l",null],["Sucre",100,"g",null],["Crème liquide",200,"ml",null],["Pistaches, amandes et noisettes",100,"g","concassées"],["Raisins secs",50,"g",null],["Noix de coco râpée",30,"g",null],["Vanille",1,"c. à thé",null]],"steps":["Disposer la pâte feuilletée émiettée dans un plat avec les fruits secs, les raisins et la coco.","Chauffer le lait avec le sucre et la vanille.","Verser le lait chaud sur la pâte.","Napper de crème.","Gratiner 15 à 20 minutes à 220 °C jusqu’à ce que le dessus soit doré; servir chaud."],"photo":{"file":"File:Om Ali in Khal el Khalili.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Om_Ali_in_Khal_el_Khalili.jpg/1280px-Om_Ali_in_Khal_el_Khalili.jpg","page":"https://commons.wikimedia.org/wiki/File:Om_Ali_in_Khal_el_Khalili.jpg","author":"Fred Cherrygarden","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"feteer-meshaltet","country":"EG","original":"Feteer meshaltet","title":"Feteer meshaltet (feuilleté égyptien au beurre clarifié)","en":"Egyptian feteer meshaltet","es":"Feteer meshaltet egipcio","desc":"Pâte étirée très finement, beurrée et repliée en couches, cuite au four jusqu’à être feuilletée et dorée; servie avec miel, fromage vieux ou mélasse.","cat":"Pain","diff":"hard","prep":60,"cook":25,"serv":6,"reference":"https://en.wikipedia.org/wiki/Feteer_meshaltet","ing":[["Farine",500,"g",null],["Eau tiède",300,"ml",null],["Sel",1,"c. à thé",null],["Beurre clarifié (samna)",200,"g","fondu"],["Miel ou mélasse",1,"portion","pour servir"]],"steps":["Pétrir farine, eau et sel 10 minutes; diviser en 4 boules, enduire de samna et reposer 30 minutes.","Étirer chaque boule sur un plan beurré jusqu’à ce qu’elle soit transparente.","Badigeonner de samna et plier en carré; superposer les carrés pliés en enfermant les couches.","Aplatir légèrement et badigeonner le dessus.","Cuire 20 à 25 minutes à 230 °C jusqu’à ce qu’il soit doré; servir chaud avec miel."],"photo":{"file":"File:Egyptian-feteer.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Egyptian-feteer.jpg/1280px-Egyptian-feteer.jpg","page":"https://commons.wikimedia.org/wiki/File:Egyptian-feteer.jpg","author":"Turnopoems","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chicken-inasal-bacolod","country":"PH","place":{"slug":"ph-bacolod","name":"Bacolod","type":"city","lat":10.6765,"lng":122.9509,"summary":"Capitale du Negros occidental, la « ville du sourire », patrie du chicken inasal."},"original":"Chicken inasal","title":"Chicken inasal de Bacolod (poulet grillé au citronnelle et rocou)","en":"Bacolod chicken inasal","es":"Chicken inasal de Bacolod","desc":"Poulet mariné au vinaigre de coco, calamansi, citronnelle et gingembre, grillé au charbon en le badigeonnant d’huile de rocou; servi avec riz et sinamak.","cat":"Plat principal","diff":"medium","prep":20,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Chicken_inasal","ing":[["Cuisses de poulet",1.2,"kg",null],["Vinaigre de coco",120,"ml",null],["Jus de calamansi ou citron vert",60,"ml",null],["Citronnelle",3,"tiges","pilées"],["Gingembre",30,"g","râpé"],["Ail",6,"gousses",null],["Huile de rocou (achuete)",80,"ml",null],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Mixer vinaigre, calamansi, citronnelle, gingembre, ail, sel et poivre; mariner le poulet au moins 4 heures.","Enfiler les morceaux sur des brochettes.","Griller sur braise moyenne 25 à 30 minutes en retournant.","Badigeonner régulièrement d’huile de rocou mêlée à un peu de marinade.","Servir avec riz arrosé d’huile de rocou et sauce soja-calamansi-piment."],"photo":{"file":"File:Chicken inasal (Philippines).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Chicken_inasal_%28Philippines%29.jpg/1280px-Chicken_inasal_%28Philippines%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Chicken_inasal_(Philippines).jpg","author":"Obsidian Soul","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"bagnet-ilocos","country":"PH","place":{"slug":"ph-ilocos","name":"Ilocos","type":"region","lat":17.6,"lng":120.6,"summary":"Région du nord-ouest de Luçon (Vigan, Laoag), terre du bagnet et de l’empanada ilocane."},"original":"Bagnet","title":"Bagnet ilocano (poitrine de porc frite deux fois)","en":"Ilocano bagnet (twice-fried pork belly)","es":"Bagnet ilocano (panceta frita dos veces)","desc":"Poitrine de porc bouillie à l’ail et au laurier, séchée puis frite deux fois jusqu’à une couenne boursouflée; servie avec bagoong et tomates.","cat":"Plat principal","diff":"medium","prep":20,"cook":90,"serv":6,"reference":"https://en.wikipedia.org/wiki/Bagnet","ing":[["Poitrine de porc en morceau",1.5,"kg",null],["Ail",1,"tête",null],["Laurier",3,"feuilles",null],["Poivre en grains",1,"c. à thé",null],["Sel",2,"c. à soupe",null],["Huile",1.5,"l","pour la friture"],["Bagoong et tomates",1,"portion","pour servir"]],"steps":["Cuire le porc 45 minutes dans l’eau avec ail, laurier, poivre et sel.","Égoutter et laisser sécher plusieurs heures (ou une nuit au réfrigérateur, à découvert).","Frire une première fois à 160 °C 15 minutes; laisser refroidir.","Refrire à 190 °C jusqu’à ce que la couenne cloque et devienne croustillante.","Couper en morceaux et servir avec bagoong, tomates et oignons."],"photo":{"file":"File:Cafe Roces Bagnet.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Cafe_Roces_Bagnet.jpg/1280px-Cafe_Roces_Bagnet.jpg","page":"https://commons.wikimedia.org/wiki/File:Cafe_Roces_Bagnet.jpg","author":"Yvette Tan","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"piaya-negros","country":"PH","place":{"slug":"ph-bacolod","name":"Bacolod","type":"city","lat":10.6765,"lng":122.9509,"summary":"Capitale du Negros occidental, la « ville du sourire », patrie du chicken inasal."},"original":"Piaya","title":"Piaya de Negros (galette fourrée au muscovado)","en":"Negrense piaya (muscovado-filled flatbread)","es":"Piaya de Negros","desc":"Galette plate sans levain fourrée de sucre muscovado et parsemée de sésame, cuite sur plaque; douceur de la province sucrière du Negros.","cat":"Dessert","diff":"medium","prep":30,"cook":20,"serv":12,"reference":"https://en.wikipedia.org/wiki/Piaya_(food)","ing":[["Farine",350,"g",null],["Saindoux ou beurre",80,"g",null],["Eau froide",120,"ml",null],["Sel",0.5,"c. à thé",null],["Sucre muscovado",200,"g",null],["Farine (garniture)",40,"g",null],["Graines de sésame",3,"c. à soupe",null]],"steps":["Sabler farine, saindoux et sel, ajouter l’eau et former une pâte; reposer 20 minutes.","Mélanger muscovado et farine de garniture avec une cuillère d’eau.","Diviser la pâte en 12 boules, les aplatir, garnir et refermer; aplatir en disques de 5 mm.","Parsemer de sésame et presser.","Cuire sur une plaque à feu moyen 4 à 5 minutes par face."],"photo":{"file":"File:Hot piaya.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Hot_piaya.jpg/1280px-Hot_piaya.jpg","page":"https://commons.wikimedia.org/wiki/File:Hot_piaya.jpg","author":"Kramthenik27","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"pancit-habhab-lucban","country":"PH","place":{"slug":"ph-lucban","name":"Lucban","type":"city","lat":14.1133,"lng":121.5569,"summary":"Ville de la province de Quezon, célèbre pour sa fête des Pahiyas et le pancit habhab."},"original":"Pancit habhab","title":"Pancit habhab de Lucban (nouilles sautées mangées sur feuille de bananier)","en":"Lucban pancit habhab","es":"Pancit habhab de Lucban","desc":"Nouilles miki sautées avec porc, saucisse longganisa, légumes et sauce soja, servies sur un carré de feuille de bananier et mangées sans couverts, avec du vinaigre.","cat":"Cuisine de rue","diff":"easy","prep":20,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Pancit_habhab","ing":[["Nouilles miki ou nouilles aux œufs fraîches",400,"g",null],["Poitrine de porc",200,"g","en lanières"],["Saucisse longganisa",2,null,"tranchée"],["Chou et carottes",250,"g","émincés"],["Oignon et ail",1,"portion",null],["Sauce soja",3,"c. à soupe",null],["Bouillon",300,"ml",null],["Vinaigre de canne",1,"portion","pour servir"],["Feuilles de bananier",4,null,null]],"steps":["Faire revenir ail, oignon, porc et longganisa.","Ajouter les légumes et sauter 2 minutes.","Verser bouillon et sauce soja, porter à ébullition.","Ajouter les nouilles et cuire en remuant jusqu’à absorption.","Servir sur des carrés de feuille de bananier, arrosé de vinaigre."],"photo":{"file":"File:Pansit Habhab of Quezon Province.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Pansit_Habhab_of_Quezon_Province.jpg/1280px-Pansit_Habhab_of_Quezon_Province.jpg","page":"https://commons.wikimedia.org/wiki/File:Pansit_Habhab_of_Quezon_Province.jpg","author":"Sheena Aloner","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"vigan-empanada","country":"PH","place":{"slug":"ph-vigan","name":"Vigan","type":"city","lat":17.5747,"lng":120.3869,"summary":"Ville coloniale classée à l’UNESCO, célèbre pour son empanada orange."},"original":"Empanada de Vigan","title":"Empanada de Vigan (chausson orange à la papaye, œuf et longganisa)","en":"Vigan empanada","es":"Empanada de Vigan","desc":"Chausson croustillant de pâte de riz teintée au rocou, garni de papaye verte râpée, d’un œuf entier et de saucisse longganisa, frit et servi avec vinaigre épicé.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Empanada#Philippines","ing":[["Farine de riz",250,"g",null],["Farine",50,"g",null],["Eau",250,"ml",null],["Rocou (achuete)",1,"c. à thé",null],["Papaye verte râpée",200,"g",null],["Longganisa de Vigan",2,null,"émiettée"],["Œufs",4,null,null],["Huile",750,"ml","pour la friture"],["Vinaigre de canne pimenté",1,"portion","pour servir"],["Sel",1,"c. à thé",null]],"steps":["Mélanger farines, eau, rocou et sel en pâte souple; former 4 disques fins sur des feuilles de bananier.","Garnir chaque disque de papaye râpée, de longganisa et d’un œuf cru.","Replier en demi-lune en s’aidant de la feuille et souder les bords.","Glisser dans l’huile à 180 °C et frire 5 à 6 minutes jusqu’à ce qu’il soit doré.","Servir avec vinaigre de canne pimenté."],"photo":{"file":"File:Local delicacy in Vigan called Empanada.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Local_delicacy_in_Vigan_called_Empanada.jpg/1280px-Local_delicacy_in_Vigan_called_Empanada.jpg","page":"https://commons.wikimedia.org/wiki/File:Local_delicacy_in_Vigan_called_Empanada.jpg","author":"Herbertkikoy","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"rakfisk-valdres","country":"NO","place":{"slug":"no-valdres","name":"Valdres","type":"region","lat":61,"lng":9.2,"summary":"Vallée de l’intérieur de la Norvège, capitale du rakfisk (Fagernes)."},"original":"Rakfisk","title":"Rakfisk de Valdres (truite fermentée sur lefse)","en":"Valdres rakfisk (fermented trout)","es":"Rakfisk de Valdres (trucha fermentada)","desc":"Truite fermentée plusieurs mois en saumure, tranchée et servie crue sur lefse ou flatbrød avec oignon rouge, crème aigre et pommes de terre; spécialité de Valdres.","cat":"Poisson","diff":"hard","prep":30,"cook":0,"serv":6,"reference":"https://en.wikipedia.org/wiki/Rakfisk","ing":[["Truites très fraîches",2,"kg","vidées et lavées"],["Sel",150,"g",null],["Sucre",20,"g",null],["Lefse ou flatbrød",6,null,"pour servir"],["Oignon rouge",1,null,"haché"],["Crème aigre (rømme)",200,"g",null],["Pommes de terre",1,"kg","cuites"]],"steps":["Rincer les truites et remplir la cavité de sel mêlé de sucre.","Les serrer dans un seau, couvrir de la saumure formée et poser un poids pour qu’elles restent immergées.","Laisser fermenter 2 à 3 mois entre 4 et 8 °C (respecter strictement l’hygiène et la température).","Lever les filets et les trancher finement.","Servir sur lefse avec oignon rouge, crème aigre et pommes de terre."],"photo":{"file":"File:Sliced rakfisk.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Sliced_rakfisk.jpg/1280px-Sliced_rakfisk.jpg","page":"https://commons.wikimedia.org/wiki/File:Sliced_rakfisk.jpg","author":"Aslak Raanes from Trondheim, Norway","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"lutefisk-no","country":"NO","original":"Lutefisk","title":"Lutefisk norvégien (morue séchée réhydratée au beurre)","en":"Norwegian lutefisk","es":"Lutefisk noruego","desc":"Stockfisch réhydraté puis traité à la lessive, cuit à la vapeur jusqu’à une texture tremblotante et servi avec beurre fondu, lard, purée de pois et pommes de terre à Noël.","cat":"Poisson","diff":"medium","prep":20,"cook":25,"serv":4,"reference":"https://en.wikipedia.org/wiki/Lutefisk","ing":[["Lutefisk prêt à cuire",1.2,"kg","en portions"],["Gros sel",1,"c. à soupe",null],["Beurre",120,"g","fondu"],["Lard",150,"g","en dés"],["Purée de pois (ertestuing)",400,"g",null],["Pommes de terre",1,"kg","cuites"],["Moutarde",1,"portion","facultatif"]],"steps":["Saler le lutefisk et le laisser 30 minutes.","Le poser dans un plat couvert et cuire 20 à 25 minutes au four à 200 °C (ou à la vapeur) sans ajouter d’eau.","Faire revenir le lard jusqu’à ce qu’il soit croustillant.","Égoutter soigneusement le poisson.","Servir avec beurre fondu, lard, purée de pois et pommes de terre."],"photo":{"file":"File:ButteredLutefisk.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/ButteredLutefisk.JPG/1280px-ButteredLutefisk.JPG","page":"https://commons.wikimedia.org/wiki/File:ButteredLutefisk.JPG","author":"Jonathunder","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"moreton-bay-bugs","country":"AU","place":{"slug":"au-moreton-bay","name":"Baie de Moreton","type":"locality","lat":-27.25,"lng":153.2,"summary":"Baie de Brisbane (Queensland) qui a donné son nom aux cigales de mer « bugs »."},"original":"Moreton Bay bugs","title":"Moreton Bay bugs grillés (cigales de mer à l’ail et au citron)","en":"Grilled Moreton Bay bugs","es":"Moreton Bay bugs a la parrilla","desc":"Cigales de mer du Queensland fendues en deux, grillées au beurre à l’ail, au citron et au persil; classique des barbecues de la côte australienne.","cat":"Fruits de mer","diff":"easy","prep":15,"cook":10,"serv":4,"reference":"https://en.wikipedia.org/wiki/Thenus_orientalis","ing":[["Moreton Bay bugs (cigales de mer) crus",8,null,null],["Beurre mou",80,"g",null],["Ail",3,"gousses","pilées"],["Citron",1,null,"zeste et jus"],["Persil",1,"poignée","haché"],["Piment",0.5,null,"facultatif"],["Sel et poivre",1,"c. à thé",null]],"steps":["Fendre les bugs en deux dans la longueur et retirer l’intestin.","Mélanger beurre, ail, zeste de citron, persil, piment, sel et poivre.","Tartiner la chair de beurre aromatisé.","Griller chair vers le bas 3 minutes, puis carapace vers le bas 3 à 4 minutes jusqu’à ce que la chair soit opaque.","Arroser de jus de citron et servir aussitôt."],"photo":{"file":"File:Cooked whole Moreton Bay Bug.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Cooked_whole_Moreton_Bay_Bug.JPG/1280px-Cooked_whole_Moreton_Bay_Bug.JPG","page":"https://commons.wikimedia.org/wiki/File:Cooked_whole_Moreton_Bay_Bug.JPG","author":"Kingturkey","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"sosaties-za","country":"ZA","original":"Sosaties","title":"Sosaties sud-africaines (brochettes marinées au curry et à l’abricot)","en":"South African sosaties","es":"Sosaties sudafricanos","desc":"Brochettes d’agneau ou de poulet marinées dans une sauce sucrée au curry, aux abricots secs et à l’oignon, d’origine malaise du Cap, grillées au braai.","cat":"Plat principal","diff":"medium","prep":30,"cook":15,"serv":6,"reference":"https://en.wikipedia.org/wiki/Sosatie","ing":[["Agneau ou poulet",1,"kg","en cubes"],["Abricots secs",150,"g",null],["Oignons",2,null,"en quartiers"],["Poivrons",2,null,"en carrés"],["Curry en poudre",2,"c. à soupe",null],["Confiture d’abricot",3,"c. à soupe",null],["Vinaigre",100,"ml",null],["Ail",2,"gousses",null],["Huile",3,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["Faire revenir un oignon émincé et l’ail dans l’huile avec le curry; ajouter confiture, vinaigre et sel, et laisser refroidir.","Mariner la viande dans cette sauce 12 à 24 heures.","Enfiler viande, abricots, oignon et poivron sur des brochettes.","Griller au braai 10 à 15 minutes en retournant et en badigeonnant.","Servir avec pap ou riz."],"photo":{"file":"File:Sosaties.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Sosaties.jpg/1280px-Sosaties.jpg","page":"https://commons.wikimedia.org/wiki/File:Sosaties.jpg","author":"Anrie","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"tamatie-bredie","country":"ZA","place":"za-cape-town","original":"Tamatie bredie","title":"Tamatie bredie (ragoût d’agneau à la tomate du Cap)","en":"Cape tomato bredie","es":"Tamatie bredie (guiso de cordero y tomate)","desc":"Ragoût d’agneau mijoté longuement avec tomates, oignons, cannelle, girofle et pommes de terre, héritage malais du Cap servi sur du riz.","cat":"Ragoût","diff":"easy","prep":20,"cook":150,"serv":6,"reference":"https://en.wikipedia.org/wiki/Bredie","ing":[["Épaule ou collier d’agneau",1.2,"kg","en morceaux"],["Tomates",1,"kg","pelées et hachées"],["Oignons",2,null,"émincés"],["Pommes de terre",4,null,"en morceaux"],["Ail",3,"gousses",null],["Bâton de cannelle",1,null,null],["Clous de girofle",3,null,null],["Sucre",1,"c. à soupe",null],["Huile",3,"c. à soupe",null],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Faire dorer l’agneau dans l’huile, puis les oignons et l’ail.","Ajouter tomates, cannelle, girofle, sucre, sel et poivre.","Couvrir et mijoter 2 heures à feu très doux sans ajouter d’eau.","Ajouter les pommes de terre et cuire 30 minutes.","Servir sur du riz blanc."],"photo":{"file":"File:Tamatie Bredie.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/53/Tamatie_Bredie.jpg","page":"https://commons.wikimedia.org/wiki/File:Tamatie_Bredie.jpg","author":"Craigfraser","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"vetkoek-za","country":"ZA","original":"Vetkoek","title":"Vetkoek (pain frit sud-africain farci de viande hachée)","en":"South African vetkoek","es":"Vetkoek sudafricano","desc":"Boules de pâte levée frites, ouvertes et garnies de viande hachée au curry, ou servies avec confiture et fromage; en-cas populaire d’Afrique du Sud.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":30,"serv":8,"reference":"https://en.wikipedia.org/wiki/Vetkoek","ing":[["Farine",500,"g",null],["Levure sèche",7,"g",null],["Sucre",1,"c. à soupe",null],["Eau tiède",320,"ml",null],["Sel",1,"c. à thé",null],["Bœuf haché",500,"g",null],["Oignon, tomate et curry",1,"portion",null],["Huile",1,"l","pour la friture"]],"steps":["Pétrir farine, levure, sucre, sel et eau; laisser lever 1 heure.","Cuire la viande avec oignon, tomate et curry 20 minutes.","Former des boules de pâte et les aplatir légèrement.","Les frire à 170 °C 4 à 5 minutes par face jusqu’à ce qu’elles soient dorées.","Les ouvrir et les garnir de viande hachée."],"photo":{"file":"File:Vetkoek with mince-001.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Vetkoek_with_mince-001.jpg/1280px-Vetkoek_with_mince-001.jpg","page":"https://commons.wikimedia.org/wiki/File:Vetkoek_with_mince-001.jpg","author":"NJR ZA","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"coffin-bread-tainan","country":"TW","place":"tw-tainan","original":"Guan cai ban","title":"Coffin bread de Tainan (pain de mie frit fourré à la crème de fruits de mer)","en":"Tainan coffin bread","es":"Pan ataúd de Tainan","desc":"Épaisse tranche de pain de mie frite, creusée et remplie d’une sauce crémeuse au poulet, fruits de mer et légumes, refermée par son couvercle; née au marché de Chikan à Tainan.","cat":"Cuisine de rue","diff":"medium","prep":20,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Coffin_bread","ing":[["Pain de mie non tranché",4,"tranches","de 5 cm d’épaisseur"],["Blanc de poulet",150,"g","en dés"],["Crevettes et calamar",150,"g","en dés"],["Carotte, petits pois et maïs",150,"g",null],["Beurre",40,"g",null],["Farine",30,"g",null],["Lait",300,"ml",null],["Bouillon",150,"ml",null],["Huile",750,"ml","pour la friture"],["Sel et poivre blanc",1,"c. à thé",null]],"steps":["Frire les tranches de pain jusqu’à ce qu’elles soient dorées; découper un couvercle et creuser l’intérieur.","Faire fondre le beurre, ajouter la farine, puis le lait et le bouillon pour une béchamel.","Ajouter poulet, fruits de mer et légumes; cuire 5 minutes et assaisonner.","Remplir les boîtes de pain de cette garniture.","Reposer le couvercle et servir aussitôt."],"photo":{"file":"File:赤崁棺材板 (12305624473).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/%E8%B5%A4%E5%B4%81%E6%A3%BA%E6%9D%90%E6%9D%BF_%2812305624473%29.jpg/1280px-%E8%B5%A4%E5%B4%81%E6%A3%BA%E6%9D%90%E6%9D%BF_%2812305624473%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%B5%A4%E5%B4%81%E6%A3%BA%E6%9D%90%E6%9D%BF_(12305624473).jpg","author":"othree","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"mala-stinky-tofu","country":"TW","original":"Ma la chou dou fu","title":"Tofu puant mala (tofu fermenté en bouillon pimenté, Taïwan)","en":"Taiwanese mala stinky tofu","es":"Tofu apestoso mala taiwanés","desc":"Tofu fermenté mijoté dans un bouillon pimenté au poivre du Sichuan avec boudin de sang de canard et légumes, servi brûlant dans les marchés de nuit de Taïwan.","cat":"Cuisine de rue","diff":"medium","prep":15,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Stinky_tofu","ing":[["Tofu puant (chou doufu)",600,"g","en cubes"],["Boudin de sang de canard (facultatif)",200,"g","en cubes"],["Bouillon de porc",1,"l",null],["Pâte de piment fermentée (doubanjiang)",2,"c. à soupe",null],["Poivre du Sichuan",1,"c. à soupe",null],["Piments séchés",6,null,null],["Gingembre et ail",1,"portion",null],["Chou et champignons",250,"g",null],["Huile",3,"c. à soupe",null],["Oignons verts",2,null,null]],"steps":["Faire revenir piments, poivre du Sichuan, gingembre, ail et doubanjiang dans l’huile.","Verser le bouillon et mijoter 15 minutes.","Ajouter le tofu puant et le boudin de canard; mijoter 20 minutes pour qu’ils s’imprègnent.","Ajouter chou et champignons 5 minutes avant la fin.","Servir brûlant parsemé d’oignons verts."],"photo":{"file":"File:Cuisine in Taiwan 1.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Cuisine_in_Taiwan_1.jpg/1280px-Cuisine_in_Taiwan_1.jpg","page":"https://commons.wikimedia.org/wiki/File:Cuisine_in_Taiwan_1.jpg","author":"Pauloleong2002","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"nalysnyky-ua","country":"UA","original":"Nalysnyky","title":"Nalysnyky ukrainiens (crêpes roulées farcies aux pois et oignons frits)","en":"Ukrainian nalysnyky (filled crepes)","es":"Nalysnyky ucranianos (crepes rellenos)","desc":"Fines crêpes roulées autour d’une farce de pois cassés et d’oignons frits (ou de fromage blanc), dorées au four ou à la poêle avec de la crème.","cat":"Plat principal","diff":"medium","prep":30,"cook":40,"serv":4,"ing":[["Farine",200,"g",null],["Lait",500,"ml",null],["Œufs",3,null,null],["Huile",3,"c. à soupe",null],["Pois cassés",250,"g","cuits en purée"],["Oignons",3,null,"émincés et frits"],["Crème aigre",200,"g",null],["Beurre",40,"g",null],["Sel",1,"c. à thé",null]],"steps":["Fouetter farine, lait, œufs, huile et sel; laisser reposer 30 minutes.","Cuire de fines crêpes dans une poêle beurrée.","Mélanger la purée de pois avec les oignons frits et le sel.","Garnir chaque crêpe, plier les bords et rouler.","Les dorer au beurre ou au four 15 minutes nappées de crème aigre."],"photo":{"file":"File:Nalysnyky 043.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Nalysnyky_043.jpg/1280px-Nalysnyky_043.jpg","page":"https://commons.wikimedia.org/wiki/File:Nalysnyky_043.jpg","author":"Kagor","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"nasi-kerabu-kelantan","country":"MY","place":{"slug":"my-kelantan","name":"Kelantan","type":"region","lat":5.3,"lng":102,"summary":"État du nord-est de la Malaisie péninsulaire, patrie du nasi kerabu bleu."},"original":"Nasi kerabu","title":"Nasi kerabu du Kelantan (riz bleu aux herbes et poisson grillé)","en":"Kelantan nasi kerabu (blue herb rice)","es":"Nasi kerabu de Kelantan (arroz azul con hierbas)","desc":"Riz teinté en bleu par les fleurs de pois papillon, servi avec herbes crues émincées, noix de coco grillée, poisson ou poulet grillé, œuf salé et kerupuk; plat du Kelantan.","cat":"Riz","diff":"medium","prep":40,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Nasi_kerabu","ing":[["Riz",400,"g",null],["Fleurs de pois papillon (bunga telang)",20,null,"infusées"],["Herbes (citronnelle, kaffir, basilic, rau răm)",1,"bouquet","très finement émincées"],["Germes de soja et concombre",200,"g",null],["Noix de coco râpée grillée (kerisik)",60,"g",null],["Poisson ou poulet grillé",400,"g",null],["Œufs salés",2,null,null],["Budu ou sambal",1,"portion",null],["Kerupuk (chips de poisson)",1,"portion",null]],"steps":["Infuser les fleurs dans 600 ml d’eau chaude 10 minutes, filtrer.","Cuire le riz dans cette eau bleue.","Préparer herbes émincées, germes et concombre.","Griller le poisson ou le poulet mariné au curcuma.","Dresser le riz avec herbes, kerisik, poisson, œuf salé, sambal et kerupuk; mélanger au moment de manger."],"photo":{"file":"File:Nasi kerabu.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Nasi_kerabu.jpg/1280px-Nasi_kerabu.jpg","page":"https://commons.wikimedia.org/wiki/File:Nasi_kerabu.jpg","author":"amrufm from Shah Alam, Malaysia","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"manuk-pansuh","country":"MY","place":{"slug":"my-sarawak","name":"Sarawak","type":"region","lat":2.5,"lng":113,"summary":"État de Bornéo malaisien, pays des Iban et du poulet cuit en bambou."},"original":"Manuk pansuh","title":"Manuk pansuh (poulet iban cuit dans le bambou, Sarawak)","en":"Sarawak manuk pansuh (chicken cooked in bamboo)","es":"Manuk pansuh (pollo cocinado en bambú)","desc":"Poulet aux herbes, citronnelle, gingembre et feuilles de manioc enfermé dans un tronçon de bambou et cuit sur le feu; plat de fête des Iban du Sarawak.","cat":"Plat principal","diff":"medium","prep":30,"cook":60,"serv":4,"reference":"https://en.wikipedia.org/wiki/Pansuh","ing":[["Poulet",1,"kg","en petits morceaux"],["Citronnelle",3,"tiges","pilées"],["Gingembre et galanga",40,"g","émincés"],["Échalotes",5,null,null],["Feuilles de manioc ou de tapioca",150,"g",null],["Feuilles de lime kaffir",4,null,null],["Sel",1.5,"c. à thé",null],["Tronçons de bambou (ou cocotte)",2,null,null]],"steps":["Mélanger poulet, aromates, feuilles et sel avec 150 ml d’eau.","Remplir les tronçons de bambou et les boucher avec des feuilles de manioc roulées.","Poser le bambou incliné au-dessus des braises et cuire 45 à 60 minutes en le tournant.","Sans bambou : cuire à couvert en cocotte 45 minutes à feu doux.","Verser le poulet et son bouillon parfumé dans un plat et servir avec du riz."],"photo":{"file":"File:Manuk pansuh.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/29/Manuk_pansuh.jpg","page":"https://commons.wikimedia.org/wiki/File:Manuk_pansuh.jpg","author":"Song GK","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"pastelitos-andinos","country":"VE","place":{"slug":"ve-merida","name":"Mérida","type":"city","lat":8.5897,"lng":-71.1561,"summary":"Ville des Andes vénézuéliennes, connue pour ses pastelitos et sa pisca andina."},"original":"Pastelitos andinos","title":"Pastelitos andinos de Mérida (chaussons frits au riz et à la viande)","en":"Mérida Andean pastelitos","es":"Pastelitos andinos merideños","desc":"Petits chaussons à pâte fine frits, garnis d’un mélange merideño de riz, viande hachée, œuf dur et pois chiches; petit-déjeuner des Andes vénézuéliennes.","cat":"Petit-déjeuner","diff":"medium","prep":40,"cook":25,"serv":8,"ing":[["Farine",400,"g",null],["Beurre",50,"g",null],["Eau tiède",180,"ml",null],["Sucre",1,"c. à soupe",null],["Bœuf haché",300,"g",null],["Riz cuit",150,"g",null],["Œufs durs",2,null,"hachés"],["Pois chiches cuits",100,"g",null],["Oignon, poivron et ail",1,"portion",null],["Huile",750,"ml","pour la friture"],["Sel",1.5,"c. à thé",null]],"steps":["Pétrir farine, beurre, eau, sucre et sel; reposer 30 minutes.","Cuire la viande avec oignon, poivron et ail; ajouter riz, pois chiches et œufs.","Étaler la pâte très finement et découper des disques de 10 cm.","Garnir, replier et souder les bords à la fourchette.","Frire à 180 °C jusqu’à ce qu’ils soient dorés et bullés."],"photo":{"file":"File:Pastelitos andinos.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Pastelitos_andinos.jpg/1280px-Pastelitos_andinos.jpg","page":"https://commons.wikimedia.org/wiki/File:Pastelitos_andinos.jpg","author":"Raymvc97","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"cachitos-de-chocolate","country":"VE","original":"Cachitos de chocolate","title":"Cachitos vénézuéliens au chocolat (croissants de boulangerie)","en":"Venezuelan chocolate cachitos","es":"Cachitos de chocolate venezolanos","desc":"Petits pains briochés roulés en croissant autour d’une barre de chocolat (ou de jambon pour la version salée), vendus chauds dans toutes les panaderías du Venezuela.","cat":"Petit-déjeuner","diff":"medium","prep":40,"cook":20,"serv":12,"reference":"https://en.wikipedia.org/wiki/Cachito","ing":[["Farine",500,"g",null],["Lait tiède",250,"ml",null],["Levure sèche",7,"g",null],["Sucre",80,"g",null],["Beurre mou",100,"g",null],["Œuf",1,null,null],["Sel",1,"c. à thé",null],["Chocolat noir en bâtonnets",200,"g",null],["Jaune d’œuf (dorure)",1,null,null]],"steps":["Pétrir farine, lait, levure, sucre, œuf, beurre et sel 10 minutes; laisser lever 1 heure.","Diviser en 12 boules et les étaler en triangles allongés.","Poser un bâtonnet de chocolat à la base et rouler en croissant.","Laisser lever 45 minutes, puis dorer au jaune d’œuf.","Cuire 18 à 20 minutes à 180 °C."],"photo":{"file":"File:Cachitos de chocolate (Venezuela).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/f1/Cachitos_de_chocolate_%28Venezuela%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Cachitos_de_chocolate_(Venezuela).jpg","author":"nelson suarez","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"tuo-zaafi","country":"GH","place":{"slug":"gh-tamale","name":"Tamale","type":"city","lat":9.4008,"lng":-0.8393,"summary":"Capitale de la région Nord du Ghana, foyer du tuo zaafi."},"original":"Tuo zaafi","title":"Tuo zaafi (pâte de maïs du nord du Ghana, soupe de feuilles)","en":"Northern Ghanaian tuo zaafi","es":"Tuo zaafi del norte de Ghana","desc":"Pâte ferme de farine de maïs (ou de mil) servie avec une soupe gluante de feuilles d’ayoyo ou de gombo et un ragoût de tomate à la viande; plat de base de Tamale et du Nord.","cat":"Plat principal","diff":"medium","prep":20,"cook":60,"serv":6,"reference":"https://en.wikipedia.org/wiki/Tuo_Zaafi","ing":[["Farine de maïs",500,"g",null],["Eau",1.5,"l",null],["Feuilles d’ayoyo (corète) ou gombos",400,"g","hachés"],["Potasse ou bicarbonate",0.5,"c. à thé",null],["Bœuf ou chèvre",600,"g","en morceaux"],["Tomates",4,null,"mixées"],["Oignons",2,null,null],["Dawadawa (soumbala)",1,"c. à soupe",null],["Piment",1,null,null],["Sel",1.5,"c. à thé",null]],"steps":["Cuire la viande avec oignon, tomates, dawadawa, piment et sel 45 minutes en ragoût.","Cuire les feuilles 10 minutes avec la potasse et un peu d’eau, puis les battre jusqu’à texture gluante.","Pour le tuo, délayer un tiers de la farine dans l’eau froide, porter à ébullition en remuant.","Ajouter le reste de farine petit à petit en battant énergiquement jusqu’à une pâte lisse et ferme; cuire 10 minutes.","Façonner en boules et servir avec la soupe de feuilles et le ragoût."],"photo":{"file":"File:Tuo zaafi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Tuo_zaafi.jpg/1280px-Tuo_zaafi.jpg","page":"https://commons.wikimedia.org/wiki/File:Tuo_zaafi.jpg","author":"Kwameghana","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"ghanaian-jollof","country":"GH","place":"gh-accra","original":"Ghanaian jollof rice","title":"Jollof ghanéen (riz basmati à la tomate et aux épices)","en":"Ghanaian jollof rice","es":"Arroz jollof ghanés","desc":"Riz parfumé cuit dans une base de tomate, piment, gingembre et ail avec bouillon et épices, servi avec poulet frit et shito; grand rival du jollof nigérian.","cat":"Riz","diff":"medium","prep":20,"cook":50,"serv":6,"reference":"https://en.wikipedia.org/wiki/Jollof_rice","ing":[["Riz basmati ou parfumé",500,"g","rincé"],["Tomates",4,null,null],["Concentré de tomate",3,"c. à soupe",null],["Oignons",2,null,null],["Poivron rouge",1,null,null],["Piment scotch bonnet",1,null,null],["Gingembre et ail",2,"c. à soupe","pilés"],["Bouillon de poulet",700,"ml",null],["Curry, thym et laurier",1,"portion",null],["Huile",100,"ml",null],["Sel",1.5,"c. à thé",null]],"steps":["Mixer tomates, un oignon, poivron, piment, gingembre et ail.","Faire revenir le second oignon dans l’huile, ajouter le concentré 5 minutes puis la purée mixée; réduire 15 minutes.","Ajouter épices, laurier, bouillon et sel; porter à ébullition.","Ajouter le riz, couvrir d’aluminium et du couvercle, cuire 25 minutes à feu très doux.","Égrener et servir avec poulet frit, salade et shito."],"photo":{"file":"File:Ghanaian Jollof Rice.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/84/Ghanaian_Jollof_Rice.jpg","page":"https://commons.wikimedia.org/wiki/File:Ghanaian_Jollof_Rice.jpg","author":"Charles Haynes","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"kokonte-gh","country":"GH","original":"Kokonte","title":"Kokonte ghanéen (pâte de manioc séché, soupe d’arachide)","en":"Ghanaian kokonte","es":"Kokonte ghanés","desc":"Pâte brune et souple de farine de manioc séché, servie avec une soupe d’arachide ou de palme au poisson fumé; surnommée « face the wall ».","cat":"Accompagnement","diff":"easy","prep":10,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Kokonte","ing":[["Farine de kokonte (manioc séché)",400,"g",null],["Eau",1,"l",null],["Sel",0.5,"c. à thé",null],["Soupe d’arachide au poisson ou poulet",1.2,"l","pour servir"]],"steps":["Délayer 100 g de farine dans 300 ml d’eau froide.","Porter le reste d’eau à ébullition et y verser le mélange en remuant.","Ajouter le reste de farine petit à petit en battant vigoureusement avec une spatule.","Cuire 10 minutes à feu doux en continuant à battre jusqu’à pâte lisse.","Façonner en boules et servir dans la soupe d’arachide."],"photo":{"file":"File:Kokonte Dish.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Kokonte_Dish.jpg/1280px-Kokonte_Dish.jpg","page":"https://commons.wikimedia.org/wiki/File:Kokonte_Dish.jpg","author":"Iamrobotboy","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"frita-cubana","country":"CU","place":"cu-havana","original":"Frita cubana","title":"Frita cubaine (burger épicé aux pommes paille)","en":"Cuban frita","es":"Frita cubana","desc":"Galette de bœuf et chorizo assaisonnée au paprika, glissée dans un petit pain avec oignons et une montagne de pommes paille; casse-croûte des rues de La Havane.","cat":"Cuisine de rue","diff":"easy","prep":20,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Frita","ing":[["Bœuf haché",400,"g",null],["Chorizo",100,"g","haché"],["Paprika",1,"c. à thé",null],["Ail et cumin",1,"c. à thé",null],["Ketchup",2,"c. à soupe",null],["Petits pains ronds",4,null,null],["Oignon",1,null,"haché"],["Pommes paille",150,"g",null],["Sel",1,"c. à thé",null]],"steps":["Mélanger bœuf, chorizo, paprika, ail, cumin, ketchup et sel.","Former 4 galettes fines.","Les cuire à la plancha 3 minutes par face.","Toaster les petits pains.","Garnir de la galette, d’oignon haché et d’une généreuse couche de pommes paille."],"photo":{"file":"File:Frita and guarapo.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Frita_and_guarapo.jpg/1280px-Frita_and_guarapo.jpg","page":"https://commons.wikimedia.org/wiki/File:Frita_and_guarapo.jpg","author":"Eugene Kim","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"roti-fiji","country":"FJ","original":"Roti fidjien","title":"Roti fidjien roulé au curry (Indo-Fidjiens)","en":"Fijian roti wrap","es":"Roti fiyiano enrollado","desc":"Roti souple de farine de blé roulé autour d’un curry de légumes, de pommes de terre ou de poulet, emporté dans un film; casse-croûte des marchés de Suva et Lautoka.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":30,"serv":6,"reference":"https://en.wikipedia.org/wiki/Roti","ing":[["Farine",500,"g",null],["Eau tiède",300,"ml",null],["Huile",3,"c. à soupe",null],["Sel",1,"c. à thé",null],["Pommes de terre",4,null,"en dés"],["Pois chiches cuits",200,"g",null],["Masala fidjien ou curry",2,"c. à soupe",null],["Oignon et ail",1,"portion",null],["Feuilles de curry",8,null,null]],"steps":["Pétrir farine, eau, huile et sel en pâte souple; reposer 30 minutes.","Faire revenir oignon, ail, feuilles de curry et masala; ajouter pommes de terre, pois chiches et un peu d’eau; cuire 20 minutes jusqu’à ce que le curry soit épais.","Étaler la pâte en disques fins et les cuire sur une tawa 1 minute par face.","Garnir chaque roti de curry et le rouler serré.","Emballer dans un film pour garder chaud."],"photo":{"file":"File:Roti's in Fiji (1813280104).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Roti%27s_in_Fiji_%281813280104%29.jpg/1280px-Roti%27s_in_Fiji_%281813280104%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Roti%27s_in_Fiji_(1813280104).jpg","author":"RodBland","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"riz-a-la-tchadienne","country":"TD","original":"Riz à la tchadienne","title":"Riz à la tchadienne (riz rouge épicé, poisson frit et légumes)","en":"Chadian-style rice plate","es":"Arroz al estilo chadiano","desc":"Riz cuit dans une base de tomate et d’épices, servi avec poisson frit, banane plantain, feuilles de vigne farcies, crudités et pomme de terre; assiette des fêtes au Tchad.","cat":"Riz","diff":"medium","prep":30,"cook":45,"serv":6,"ing":[["Riz",500,"g",null],["Concentré de tomate",3,"c. à soupe",null],["Oignons",2,null,"hachés"],["Ail et gingembre",1,"c. à soupe","pilés"],["Curry et piment",2,"c. à thé",null],["Poisson (capitaine, tilapia)",1,"kg","en tranches"],["Bananes plantains mûres",2,null,null],["Crudités (laitue, tomate, concombre)",1,"portion",null],["Huile",250,"ml",null],["Sel",2,"c. à thé",null]],"steps":["Faire revenir oignons, ail et gingembre dans 4 c. à soupe d’huile, ajouter concentré et épices.","Ajouter le riz, 1 litre d’eau et le sel; couvrir et cuire 25 minutes.","Saler et frire les tranches de poisson jusqu’à ce qu’elles soient dorées.","Frire les plantains en rondelles.","Dresser le riz avec poisson, plantains et crudités."],"photo":{"file":"File:Riz sauté à la tchadienne.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Riz_saut%C3%A9_%C3%A0_la_tchadienne.jpg/1280px-Riz_saut%C3%A9_%C3%A0_la_tchadienne.jpg","page":"https://commons.wikimedia.org/wiki/File:Riz_saut%C3%A9_%C3%A0_la_tchadienne.jpg","author":"Fatakaya","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"boule-sauce-cawal","country":"TD","original":"Boule sauce cawal","title":"Boule de mil à la sauce cawal (gombo sec et feuilles fermentées, Tchad)","en":"Chadian millet boule with cawal sauce","es":"Bola de mijo con salsa cawal (Chad)","desc":"Boule ferme de farine de mil servie avec une sauce gluante de gombo sec et de cawal (feuilles fermentées), viande séchée et piment; repas quotidien au Tchad.","cat":"Plat principal","diff":"medium","prep":20,"cook":60,"serv":6,"ing":[["Farine de mil",600,"g",null],["Eau",2,"l",null],["Gombo sec en poudre",4,"c. à soupe",null],["Cawal (feuilles fermentées) ou soumbala",2,"c. à soupe",null],["Viande séchée ou poisson fumé",200,"g",null],["Oignon",1,null,"haché"],["Piment",1,null,null],["Huile",3,"c. à soupe",null],["Natron ou bicarbonate",0.5,"c. à thé",null],["Sel",1,"c. à thé",null]],"steps":["Faire revenir l’oignon dans l’huile, ajouter viande séchée, cawal, piment et 1 litre d’eau; cuire 30 minutes.","Fouetter la poudre de gombo et le natron dans la sauce jusqu’à ce qu’elle devienne gluante; saler.","Pour la boule, verser la farine en pluie dans 1 litre d’eau bouillante en battant fortement.","Cuire 10 minutes à couvert en remuant, jusqu’à pâte ferme et lisse.","Mouler la boule dans un bol mouillé et la servir avec la sauce."],"photo":{"file":"File:Boule avec sauce de gombo sec en plus \"cawal\" (Tchad).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Boule_avec_sauce_de_gombo_sec_en_plus_%22cawal%22_%28Tchad%29.jpg/1280px-Boule_avec_sauce_de_gombo_sec_en_plus_%22cawal%22_%28Tchad%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Boule_avec_sauce_de_gombo_sec_en_plus_%22cawal%22_(Tchad).jpg","author":"Abdeldjelil Souleyman","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}}]$batch$::jsonb);
